    parent = list(range(n))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        root_x = find(x)
        root_y = find(y)
        if root_x != root_y:
            parent[root_y] = root_x

    for u, v in edges:
        union(u, v)

    components = set()
    for i in range(n):
        components.add(find(i))

    return len(components)

